import Replicate from "replicate";

export const replicate = new Replicate({ auth: process.env.REPLICATE_API_TOKEN });

export async function generateImage(
  prompt: string,
  model = "black-forest-labs/flux-schnell",
): Promise<string[]> {
  const output = await replicate.run(model as `${string}/${string}`, {
    input: { prompt, num_outputs: 1 },
  });
  return Array.isArray(output) ? (output as string[]) : [output as string];
}

export async function runModel<TInput extends object, TOutput>(
  model: `${string}/${string}`,
  input: TInput,
): Promise<TOutput> {
  return replicate.run(model, { input }) as Promise<TOutput>;
}

